  <div class="flex items-center gap-3 text-neutral-800">
    <a routerLink="/" class="flex items-center gap-3 text-neutral-800">
      <div class="size-6 text-[#141414]">
        <svg fill="none" viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg">
          <g clip-path="url(#clip0_6_319)">
            <path d="M8.57829 8.57829C5.52816 11.6284 3.451 15.5145 2.60947 19.7452C1.76794 23.9758 2.19984 28.361 3.85056 32.3462C5.50128 36.3314 8.29667 39.7376 11.8832 42.134C15.4698 44.5305 19.6865 45.8096 24 45.8096C28.3135 45.8096 32.5302 44.5305 36.1168 42.134C39.7033 39.7375 42.4987 36.3314 44.1494 32.3462C45.8002 28.361 46.2321 23.9758 45.3905 19.7452C44.549 15.5145 42.4718 11.6284 39.4217 8.57829L24 24L8.57829 8.57829Z" fill="currentColor"></path>
          </g>
          <defs>
            <clipPath id="clip0_6_319"><rect fill="white" height="48" width="48"></rect></clipPath>
          </defs>
        </svg>
      </div>
      <h1 class="text-neutral-800 text-xl font-bold leading-tight tracking-tight">Acme Co</h1>
    </a>
  </div>
  <nav>
    <ul class="flex items-center gap-x-4">
      <li *ngIf="!(authService.isLoggedIn$ | async)">
        <a routerLink="/login" class="btn btn-outline">Log In</a>
      </li>
      <li *ngIf="!(authService.isLoggedIn$ | async)">
        <a routerLink="/signup" class="btn btn-primary">Sign Up</a>
      </li>
      <li *ngIf="authService.isLoggedIn$ | async">
        <a routerLink="/cart" class="relative">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" class="w-6 h-6">
            <path stroke-linecap="round" stroke-linejoin="round" d="M2.25 3h1.386c.51 0 .955.343 1.087.835l.383 1.437M7.5 14.25a3 3 0 0 0-3 3h15.75m-12.75-3h11.218c1.121-2.3 2.1-4.684 2.924-7.138a60.114 60.114 0 0 0-16.536-1.84M7.5 14.25 5.106 5.272M6 20.25a.75.75 0 1 1-1.5 0 .75.75 0 0 1 1.5 0Zm12.75 0a.75.75 0 1 1-1.5 0 .75.75 0 0 1 1.5 0Z" />
          </svg>
          <ng-container *ngIf="cartService.cartItems$ | async as cartItems">
            <span *ngIf="cartItems.length > 0" class="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full h-4 w-4 flex items-center justify-center">
              {{ cartItems.length }}
            </span>
          </ng-container>
        </a>
      </li>
      <li *ngIf="authService.isLoggedIn$ | async">
        <button (click)="logout()" class="btn btn-outline">Log Out</button>
      </li>
    </ul>
  </nav>
</header>
